select id, items, ship_to, attributes, forall(items, x -> x.qty <= 5) as all_small_qty, array_join(array_sort(coupon_codes), ',') as coupons_text, ship_to.city as ship_city, transform(filter(items, x -> x.promo is not null), x -> struct(x.product_id as pid, round(x.price * 0.9, 2) as discounted_price)) as promo_lines, aggregate(items, 0.0D, (acc, x) -> acc + x.qty * x.price, acc -> round(acc, 2)) as items_total from carts;
